import pandas as pd


def run(inputs: dict) -> dict:
    dim_price = inputs["dim_price"].copy()
    stg_price = inputs["stg_price"].copy()
    batch_control = inputs["batch_control"].copy()

    batch_date = batch_control["batch_date"].iloc[0]

    # Build per-product list of version dicts from existing dim_price
    versions_by_product = {}
    for _, row in dim_price.iterrows():
        pid = row["product_id"]
        versions_by_product.setdefault(pid, []).append({
            "list_price": row["list_price"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
        })

    # Sort staged rows by product_id, then effective_date ascending
    stg_sorted = stg_price.sort_values(["product_id", "effective_date"], kind="mergesort")

    # Process each product's staged rows in order
    for pid, group in stg_sorted.groupby("product_id", sort=False):
        versions = versions_by_product.get(pid, [])

        # determine current tail: version with latest eff_start_date
        if versions:
            tail = max(versions, key=lambda v: v["eff_start_date"])
        else:
            tail = None

        for _, srow in group.iterrows():
            s_price = srow["list_price"]
            s_date = srow["effective_date"]

            if tail is not None and tail["list_price"] == s_price:
                # unchanged, skip - no new version
                continue
            else:
                if tail is not None:
                    tail["eff_end_date"] = s_date
                new_version = {
                    "list_price": s_price,
                    "eff_start_date": s_date,
                    "eff_end_date": pd.NaT,
                }
                versions.append(new_version)
                tail = new_version

        versions_by_product[pid] = versions

    # Flatten all versions into output rows
    out_rows = []
    for pid, versions in versions_by_product.items():
        for v in versions:
            eff_start = v["eff_start_date"]
            eff_end = v["eff_end_date"]

            if pd.isna(eff_end):
                is_current = 1 if eff_start <= batch_date else 0
            else:
                is_current = 1 if (eff_start <= batch_date) and (batch_date < eff_end) else 0

            out_rows.append({
                "product_id": pid,
                "list_price": v["list_price"],
                "eff_start_date": eff_start,
                "eff_end_date": eff_end,
                "is_current": is_current,
            })

    out_df = pd.DataFrame(out_rows, columns=[
        "product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"
    ])

    # Enforce dtypes
    out_df["product_id"] = out_df["product_id"].astype("int64")
    out_df["list_price"] = out_df["list_price"].astype("float64")
    out_df["eff_start_date"] = pd.to_datetime(out_df["eff_start_date"])
    out_df["eff_end_date"] = pd.to_datetime(out_df["eff_end_date"])
    out_df["is_current"] = out_df["is_current"].astype("int64")

    out_df = out_df.sort_values(["product_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)

    return {"dim_price_out": out_df}
